#include <unistd.h>
#include <sys/msg.h>

struct msg_t {
	long mtype;
	char mtext[16];
};

int main(int argc, char *argv[]) { 
    // create a message queue
	key_t key = ftok("important_config", 0);
	int msg_id = msgget(key, 0644);

