	struct msg_t msg_recv;
	msgrcv(msg_id, &msg_recv, sizeof(msg_recv.mtext), 1, 0);
	printf("%s\n", msg_recv.mtext);

	// remove the message queue
	msgctl(msg_id, IPC_RMID, NULL);

	return 0;
}
