## 2. 进程间通信

### 2.1 管道

管道是一种半双工的通信方式，数据只能单向流动，而且只能在具有亲缘关系的进程间使用。

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>

int main(int argc, char *argv[]) { 
    int pipefd[2];

    // 创建一个管道
    if (pipe(pipefd) < 0) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // 父进程
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // 子进程
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        execlp("ls", "ls", "-l", NULL);
        exit(EXIT_SUCCESS);
    } else {
        // 父进程
        close(pipefd[1]);
        dup2(pipefd[0], STDIN_FILENO);
        execlp("grep", "grep", "important", NULL);
        exit(EXIT_SUCCESS);
    }
}
```

