		perror("shmget");
		exit(EXIT_FAILURE);
	}

    // attach the shared memory segment to the current process
	void *shm_addr = shmat(shm_id, NULL, 0);
	if (shm_addr == (void *)-1) {
		perror("shmat");
		exit(EXIT_FAILURE);
	}

