	char *shm_data = shm_addr;
	strcpy(shm_data, "important config");

    // detach the shared memory segment from the current process
	if (shmdt(shm_addr) == -1) {
		perror("shmdt");
		exit(EXIT_FAILURE);
	}

    // remove the shared memory segment
	if (shmctl(shm_id, IPC_RMID, NULL) == -1) {
		perror("shmctl");
		exit(EXIT_FAILURE);
	}

    return 0;
}
