int main(int argc, char *argv[]) {
    // get a directory name from the command line
    char *dirname = argv[1];

    // open the directory
    int dirfd = open(dirname, O_RDONLY);
    if (dirfd < 0) {
        perror("open");
        exit(1);
    }

    // read the directory
    DIR *dir = fdopendir(dirfd);
    if (dir == NULL) {
        perror("fdopendir");
        exit(1);
    }

    // list the contents of that directory
    struct dirent *entry;
    while ((entry = readdir(dir))!= NULL) {
        printf("%s\n", entry->d_name);
    }

    // close the directory
    closedir(dir);

    return 0;
}
